import Link from '@jetbrains/ring-ui-built/components/link/link'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'

import {useUserProperty} from '../../../../hooks/useUserProperty'
import {UserProperties} from '../../../../utils/userProperties'

export default function FavoriteBuildsSettingsMessage() {
  const addTriggeredBuildToFavorites = useUserProperty(
    UserProperties.ADD_TRIGGERED_BUILD_TO_FAVORITES,
  )

  if (addTriggeredBuildToFavorites !== 'true') {
    return null
  }

  return (
    <div>
      {
        'All manually triggered builds are added to favorites. This behavior can be disabled in the '
      }
      <Link href={resolveRelative('/profile.html')}>{'user profile settings'}</Link>
      {'.'}
    </div>
  )
}
